out = StringIO.new
real = $stdout
$stdout = out
ZONES.each do |z|
  AS.use_zone(z) do
    offsets = NOWS.map { |t| AS.travel(t.to_i - Time.now.to_i); AS.now.utc_offset }
    AS.travel(0)
    puts "#{z} now_offset #{NOWS.zip(offsets).map { |t, o| "#{t.strftime("%Y-%m-%d")} #{o}" }.join(" ")}"
    STORED.each do |s|
      t = AS.parse_db_time(s)
      puts "#{z} stored #{s} => #{t.strftime(F)} bod #{AS.beginning_of_day(t).strftime(F)} eod #{AS.end_of_day(t).strftime(F)} nm #{AS.months_since(t).strftime(F)} ds #{AS.days_since(t, 1).strftime(F)} bow #{AS.beginning_of_week(t).strftime(F)}"
    end
    PARSED.each { |s| puts "#{z} parse #{s} => #{AS.zone_parse(s).strftime(F)}" }
    puts "#{z} in_jakarta #{AS.in_time_zone(Time.utc(2021, 8, 1, 12), "Asia/Jakarta").strftime(F)}"
  end
end
AS.use_zone("Asia/Tokyo") { AS.use_zone("America/New_York") { puts "nested inner #{AS.now.utc_offset.abs > 0}" }; puts "nested outer #{AS.now.utc_offset}" }
puts "after #{AS.now.utc_offset}"
begin; AS.use_zone("Mars/Base") { }; rescue ArgumentError => e; puts "invalid #{e.message}"; end
$stdout = real
failures = []
got = out.string.split("\n")
want = WANT.split("\n")
want.each_with_index { |w, i| failures << "line #{i + 1}: want #{w.inspect}, got #{got[i].inspect}" unless got[i] == w }
failures << "extra output: #{got[want.length..].inspect}" if got.length > want.length

seen = []
worker = Thread.new { AS.use_zone("Asia/Tokyo") { sleep 0.2; seen << AS.now.utc_offset } }
sleep 0.05
seen << AS.now.utc_offset
worker.join
failures << "a zone leaked across threads: #{seen.inspect}" unless seen == [0, 32400]

ny = AS.find_zone!("America/New_York")
failures << "past the last transition the POSIX rule answers" unless [ny.offset_at(Time.utc(2045, 7, 1).to_i), ny.offset_at(Time.utc(2045, 12, 1).to_i)] == [-14400, -18000]

puts "cases #{want.length}"
puts failures
puts "ALL OK" if failures.empty?
exit(failures.empty? ? 0 : 1)
